    std::string_view tok_sv(const char *json, const jsmntok_t &tok)
    {
        return std::string_view(json + tok.start, static_cast<size_t>(tok.end - tok.start));
    }

    long long tok_int(const char *json, const jsmntok_t &tok)
    {
        long long value = 0;
        std::from_chars(json + tok.start, json + tok.end, value);
        return value;
    }

    // Returns the index of the first token after the subtree rooted at tokens[idx].
    int skip_value(const jsmntok_t *tokens, int idx)
    {
        const jsmntok_t &t = tokens[idx];
        if (t.type == JSMN_STRING || t.type == JSMN_PRIMITIVE)
        {
            return idx + 1;
        }
        int next = idx + 1;
        if (t.type == JSMN_OBJECT)
        {
            for (int i = 0; i < t.size; i++)
            {
                next = skip_value(tokens, next); // key
                next = skip_value(tokens, next); // value
            }
        }
        else if (t.type == JSMN_ARRAY)
        {
            for (int i = 0; i < t.size; i++)
            {
                next = skip_value(tokens, next);
            }
        }
        return next;
    }

    // Tokenizes the JSON value spanning exactly [json, json + len) -- grows the
    // token buffer and retries on JSMN_ERROR_NOMEM. Returns an empty vector on
    // any failure (malformed JSON, or pathologically large object).
    std::vector<jsmntok_t> tokenize(const char *json, size_t len, size_t initial_capacity)
    {
        std::vector<jsmntok_t> tokens(initial_capacity);
        int n;
        for (;;)
        {
            jsmn_parser p;
            jsmn_init(&p);
            n = jsmn_parse(&p, json, len, tokens.data(), static_cast<unsigned int>(tokens.size()));
            if (n != JSMN_ERROR_NOMEM)
            {
                break;
            }
            if (tokens.size() > 65536)
            {
                return {};
            }
            tokens.resize(tokens.size() * 2);
        }
        if (n < 1)
        {
            return {};
        }
        tokens.resize(static_cast<size_t>(n));
        return tokens;
    }

    struct FieldRef
    {
        bool found = false;
        const char *json = nullptr;
        jsmntok_t tok{};
    };

    // Scans the immediate keys of the JSON object spanning [obj_json, obj_json +
    // obj_len) for `key`. Re-parses that whole object every call -- by design,
    // this is not memoized across calls (see the file header comment).
    FieldRef find_field(const char *obj_json, size_t obj_len, std::string_view key)
    {
        std::vector<jsmntok_t> tokens = tokenize(obj_json, obj_len, 64);
        if (tokens.empty() || tokens[0].type != JSMN_OBJECT)
        {
            return {};
        }

        int n = tokens[0].size;
        int cur = 1;
        for (int i = 0; i < n; i++)
        {
            std::string_view k = tok_sv(obj_json, tokens[cur]);
            int val_idx = cur + 1;
            if (k == key)
            {
                return FieldRef{true, obj_json, tokens[val_idx]};
            }
            cur = skip_value(tokens.data(), cur); // skip key
            cur = skip_value(tokens.data(), cur); // skip value
        }
        return {};
    }

    // Like find_field, but for an array-valued key: returns the (start, length)
    // span of each element, without parsing into them.
    std::vector<std::pair<const char *, size_t>> find_array_field(const char *obj_json, size_t obj_len, std::string_view key)
    {
        std::vector<std::pair<const char *, size_t>> result;

        std::vector<jsmntok_t> tokens = tokenize(obj_json, obj_len, 256);
        if (tokens.empty() || tokens[0].type != JSMN_OBJECT)
        {
            return result;
        }

        int n = tokens[0].size;
        int cur = 1;
        for (int i = 0; i < n; i++)
        {
            std::string_view k = tok_sv(obj_json, tokens[cur]);
            int val_idx = cur + 1;
            if (k == key && tokens[val_idx].type == JSMN_ARRAY)
            {
                int an = tokens[val_idx].size;
                int acur = val_idx + 1;
                result.reserve(static_cast<size_t>(an));
                for (int j = 0; j < an; j++)
                {
                    const jsmntok_t &et = tokens[acur];
                    result.emplace_back(obj_json + et.start, static_cast<size_t>(et.end - et.start));
                    acur = skip_value(tokens.data(), acur);
                }
                return result;
            }
            cur = skip_value(tokens.data(), cur);
            cur = skip_value(tokens.data(), cur);
        }
        return result;
    }

    // Fills data_type/data from a point's JSON "type" string and optional "value".
    void resolve_data(std::string_view type, bool has_value, long long value, SunspecPointData &out_type, SunspecPointDataVariant &out_data)
    {
        if (type == "int16")
        {
            out_type = SunspecPointData_kSint16;
            out_data = kSint16(has_value ? static_cast<int16_t>(value) : kSint16UnimplementedValue);
        }
        else if (type == "int32")
        {
            out_type = SunspecPointData_kSint32;
            out_data = kSint32(has_value ? static_cast<int32_t>(value) : kSint32UnimplementedValue);
        }
        else if (type == "int64")
        {
            out_type = SunspecPointData_kSint64;
            out_data = kSint64(has_value ? value : kSint64UnimplementedValue);
        }
        else if (type == "raw16")
        {
            out_type = SunspecPointData_kRaw16;
            out_data = kRaw16(has_value ? static_cast<uint16_t>(value) : kRaw16UnimplementedValue);
        }
        else if (type == "uint16")
        {
            out_type = SunspecPointData_kUint16;
            out_data = kUint16(has_value ? static_cast<uint16_t>(value) : kUint16UnimplementedValue);
        }
        else if (type == "uint32")
        {
            out_type = SunspecPointData_kUint32;
            out_data = kUint32(has_value ? static_cast<uint32_t>(value) : kUint32UnimplementedValue);
        }
        else if (type == "uint64")
        {
            out_type = SunspecPointData_kUint64;
            out_data = kUint64(has_value ? static_cast<uint64_t>(value) : kUint64UnimplementedValue);
        }
        else if (type == "acc16")
        {
            out_type = SunspecPointData_kAcc16;
            out_data = kAcc16(has_value ? static_cast<uint16_t>(value) : kAcc16UnimplementedValue);
        }
        else if (type == "acc32")
        {
            out_type = SunspecPointData_kAcc32;
            out_data = kAcc32(has_value ? static_cast<uint32_t>(value) : kAcc32UnimplementedValue);
        }
        else if (type == "acc64")
        {
            out_type = SunspecPointData_kAcc64;
            out_data = kAcc64(has_value ? static_cast<uint64_t>(value) : kAcc64UnimplementedValue);
        }
        else if (type == "bitfield16")
        {
            out_type = SunspecPointData_kBitfield16;
            out_data = kBitfield16(has_value ? static_cast<uint16_t>(value) : kBit16UnimplementedValue);
        }
        else if (type == "bitfield32")
        {
            out_type = SunspecPointData_kBitfield32;
            out_data = kBitfield32(has_value ? static_cast<uint32_t>(value) : kBit32UnimplementedValue);
        }
        else if (type == "bitfield64")
        {
            out_type = SunspecPointData_kBitfield64;
            out_data = kBitfield64(has_value ? static_cast<uint64_t>(value) : kBit64UnimplementedValue);
        }
        else if (type == "enum16")
        {
            out_type = SunspecPointData_kEnum16;
            out_data = kEnum16(has_value ? static_cast<uint16_t>(value) : kEnum16UnimplementedValue);
        }
        else if (type == "enum32")
        {
            out_type = SunspecPointData_kEnum32;
            out_data = kEnum32(has_value ? static_cast<uint32_t>(value) : kEnum32UnimplementedValue);
        }
        else if (type == "float32")
        {
            out_type = SunspecPointData_kFloat32;
            out_data = kFloat32(has_value ? static_cast<float>(value) : kFloat32UnimplementedValue);
        }
        else if (type == "float64")
        {
            out_type = SunspecPointData_kFloat64;
            out_data = kFloat64(has_value ? static_cast<double>(value) : kFloat64UnimplementedValue);
        }
        else if (type == "string")
        {
            out_type = SunspecPointData_kStringx;
            out_data = kStringx(kStringUnimplementedValue); // JSON "value" is never a string on any point in the corpus today.
        }
        else if (type == "sunssf")
        {
            out_type = SunspecPointData_kSunsSf;
            out_data = kSunsSf(has_value ? static_cast<uint16_t>(value) : kSunsSfUnimplementedValue);
        }
        else if (type == "pad")
        {
            out_type = SunspecPointData_kPad16;
            out_data = kPad16(has_value ? static_cast<uint16_t>(value) : kPad16UnimplementedValue);
        }
        else if (type == "ipaddr")
        {
            out_type = SunspecPointData_kIpAddr;
            out_data = kIpAddr(kIpAddrUnimplementedValue.octet1, kIpAddrUnimplementedValue.octet2, kIpAddrUnimplementedValue.octet3, kIpAddrUnimplementedValue.octet4);
        }
        else if (type == "ipv6addr")
        {
            out_type = SunspecPointData_kIpv6Addr;
            out_data = kIpv6Addr(std::array<uint8_t, 24>{}); // NOTE: no dedicated unimplemented constant defined yet (see c_model_definition.h).
        }
        else if (type == "eui48")
        {
            out_type = SunspecPointData_kEui48;
            out_data = kEui48(std::array<uint8_t, 3>{}); // NOTE: no dedicated unimplemented constant defined yet (see c_model_definition.h).
        }
        else
        {
            out_type = SunspecPointData_NONE;
            out_data = std::monostate{};
        }
    }

