SunspecModelDef::SunspecModelDef(const char *json)
    : json_{json}, json_len_{std::strlen(json)}
{
    FieldRef f = find_field(json_, json_len_, "group");
    if (f.found && f.tok.type == JSMN_OBJECT)
    {
        group_cache_.emplace_back(f.json + f.tok.start, static_cast<size_t>(f.tok.end - f.tok.start));
    }
}

SunspecModelList SunspecModelDef::id() const
{
    FieldRef f = find_field(json_, json_len_, "id");
    if (!f.found)
    {
        return SunspecModelList_kModelInvalid;
    }
    return static_cast<SunspecModelList>(tok_int(f.json, f.tok));
}

const SunspecGroupDef *SunspecModelDef::group() const
{
    return group_cache_.empty() ? nullptr : &group_cache_.front();
}

std::string_view SunspecModelDef::label() const
{
    const SunspecGroupDef *g = group();
    return g != nullptr ? g->label() : std::string_view{};
}

